def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = []
        current_start, current_end = intervals[0]
        for start, end in intervals[1:]:
            if start <= current_end:
                current_end = max(current_end, end)
            else:
                if current_start < current_end:
                    merged.append([current_start, current_end])
                current_start, current_end = start, end
        if current_start < current_end:
            merged.append([current_start, current_end])
        return merged

    # Merge and clean up both inputs
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    result = []

    for a_start, a_end in a_merged:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            next_intervals = []
            for curr_start, curr_end in current_intervals:
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap
                    next_intervals.append([curr_start, curr_end])
                else:
                    # There is overlap, keep the non-overlapping parts
                    if curr_start < b_start:
                        next_intervals.append([curr_start, b_start])
                    if b_end < curr_end:
                        next_intervals.append([b_end, curr_end])
            current_intervals = next_intervals

        result.extend(current_intervals)

    # Merge adjacent intervals in result
    result = merge_intervals(result)

    return result

